/// <summary>
///
/// </summary>
public static void MigrateIfNeeded()
{
    TFMMenuPermissions perms;

    select sum(MenuLineNumber) from perms;  

    if (perms.MenuLineNumber > 0.5)
    {
        return;
    }

    ttsbegin;
    while select forupdate perms
    {
        perms.MenuLineNumber = perms.MenuSorting;
        perms.doUpdate();
    }
    ttscommit;

}

public static void MoveItem(TFMMenu _menuToMove, TFMMenu _menuToMoveTo, UserGroupId _groupID, TFMMenuGroupId _menuGroup)
{
    TFMMenuPermissions  permsMoveItem;
    TFMMenuPermissions  permsOtherItems;
    LineNumber          nextNumber, previousNumber;
    select firstonly MenuLineNumber from permsOtherItems order by MenuLineNumber where permsOtherItems.UserGroupId == _groupID && permsOtherItems.Menu == _menuToMoveTo && permsOtherItems.MenuGroup == _menuGroup;

    nextNumber = permsOtherItems.MenuLineNumber;
    select firstonly MenuLineNumber from permsOtherItems order by MenuLineNumber desc where permsOtherItems.UserGroupId == _groupID && permsOtherItems.MenuLineNumber < nextNumber && permsOtherItems.MenuGroup == _menuGroup;
    previousNumber = permsOtherItems.MenuLineNumber;

    ttsbegin;
    select firstonly forupdate permsMoveItem where permsMoveItem.Menu == _menuToMove && permsMoveItem.UserGroupId == _groupID && permsMoveItem.MenuGroup == _menuGroup;
    permsMoveItem.MenuLineNumber = 0.5*(nextNumber + previousNumber);
    permsMoveItem.doUpdate();
    ttscommit;

}

public static void addItem(TFMMenu _menuToAdd, UserGroupId _groupID, TFMMenuGroupId _menuGroup, LineNumber _lineNumberOverride = 0)
{
    TFMMenuPermissions  permsCheck;
    TFMMenuPermissions  perms;
    TFMMenuPermissions  permsOtherItems;

    select firstonly permsCheck where permsCheck.UserGroupId == _groupID && permsCheck.MenuGroup == _menuGroup && permsCheck.Menu == _menuToAdd;
    if(permsCheck)
    {
        return;
    }

    select firstonly permsOtherItems order by MenuLineNumber desc where permsOtherItems.UserGroupId == _groupID && permsOtherItems.MenuGroup == _menuGroup;
    if(!permsOtherItems || !permsOtherItems.MenuLineNumber)
    {
        _lineNumberOverride = 10; //make sure we start with 10.
    }

    perms.Menu = _menuToAdd;
    perms.MenuLineNumber = _lineNumberOverride ? _lineNumberOverride : permsOtherItems.MenuLineNumber +1;
    perms.UserGroupId = _groupID;
    perms.MenuGroup = _menuGroup;
    perms.insert();

}

public static void removeItem(TFMMenu _menuToRemove, UserGroupId _groupID, TFMMenuGroupId _menuGroup)
{
    TFMMenuPermissions  perms;

    ttsbegin;
    select firstonly forupdate perms where perms.UserGroupId == _groupID && perms.Menu == _menuToRemove && perms.MenuGroup == _menuGroup;
    perms.delete();
    ttscommit;

}

/// <summary>
/// Addes the default permission for menu pages so that the first time it runs the TFM-User and TFM-Admin has the default menu items.
/// </summary>
/// <param name = "_pages"></param>
/// <param name = "_userGroupID"></param>
/// <param name = "_menuGroup"></param>
public static void addDefaultMenuPermissions(TFMPages _pages, UserGroupId _userGroupID = null, TFMMenuGroupId _menuGroup = null)
{
    TFMPage             currentTFMPage;        
    MapEnumerator       pagesEnum = _pages.getPages().getEnumerator();
    SetEnumerator       categoriesEnum;
    LineNumber          lineNumberOverride;

    // create all controls for the pages.
    while (pagesEnum.moveNext())
    {
        currentTFMPage = pagesEnum.currentValue() as TFMPage;

        // Add the Menu Groups that has not been created yet.
        categoriesEnum = currentTFMPage.getPageBelongsToMenuGroups().getEnumerator();
        while(categoriesEnum.moveNext())
        {
            if((!_menuGroup || categoriesEnum.current() == _menuGroup))
            {
                if(currentTFMPage.parmAvailableForMenuPages())
                {
                    lineNumberOverride = currentTFMPage.parmId() == TFMConstants::Pick() ? 4 : (currentTFMPage.parmId() == 'Receive' ? 2 : (currentTFMPage.parmId() == 'Count' ? 6 : 0)); // to make sure the order is somewhat correct the first time the system loads.
                    TFMMenuPermissions::addMenu(currentTFMPage.parmId(), categoriesEnum.current(), _userGroupID, lineNumberOverride);
                }
            }
        }
    }
}

public static void addMenu(TFMMenu _menuName, TFMMenuGroupId _menuGroup, UserGroupId _groupID, LineNumber _lineNumberOverride)
{

    ttsbegin;

    if(_groupId)
    {
        TFMMenuPermissions::addItem(_menuName, _groupID, _menuGroup, _lineNumberOverride);
    }
    else
    {
        TFMMenuPermissions::addItem(_menuName, TFMConstants::TFMUser(), _menuGroup, _lineNumberOverride);
        TFMMenuPermissions::addItem(_menuName, TFMConstants::TFMAdmin(), _menuGroup, _lineNumberOverride);
    }

    ttscommit;
}
